import json
from pathlib import Path

root = Path(__file__).resolve().parents[1]
config = json.loads((root / 'reseller-sites.json').read_text())
rows = []
for site in config['sites']:
    rows.append('\t{Enabled: %s, PrimaryOrigin: %s, CustomerOrigin: %s},' % (
        str(site['enabled']).lower(),
        json.dumps(site['primary_origin']),
        json.dumps(site['customer_origin']),
    ))
(root / 'backend/internal/pkg/resellersite/config_gen.go').write_text(
    '// Code generated by tools/generate_reseller_sites.py; DO NOT EDIT.\n'
    'package resellersite\n\nvar configuredSites = []Site{\n' + '\n'.join(rows) + '\n}\n'
)
